import { Text, View } from '@tarojs/components';
import './equal-width-row.less';

type CardModifier = '' | 'entry-card--last' | 'entry-card--bar';

type Entry = {
  label: string;
  modifier: CardModifier;
};

type EqualWidthRowProps = {
  hasTradeIn: boolean;
};

export function EqualWidthRow({ hasTradeIn }: EqualWidthRowProps) {
  // Single entry: fall back to bar mode (full row).
  // Paired entry: only the last item carries --last to clear trailing spacing.
  const entries: Entry[] = hasTradeIn
    ? [
        { label: '金融方案', modifier: '' },
        { label: '置换估价', modifier: 'entry-card--last' },
      ]
    : [{ label: '金融方案', modifier: 'entry-card--bar' }];

  return (
    <View className="entry-row">
      {entries.map(({ label, modifier }) => (
        <View
          key={label}
          className={modifier ? `entry-card ${modifier}` : 'entry-card'}
        >
          <Text className="entry-card__title">{label}</Text>
        </View>
      ))}
    </View>
  );
}
